17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.DayOfWeek;
20	import java.time.LocalDate;
21	import java.util.ArrayList;
22	import java.util.Collection;
23	import java.util.List;
24	import java.util.regex.Pattern;
25	
26	import org.slf4j.Logger;
27	import org.slf4j.LoggerFactory;
28	import org.springframework.http.HttpHeaders;
29	import org.springframework.http.HttpStatus;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerEmailException;
32	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerHouseholdException;
33	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerTelephoneException;
34	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
35	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
36	import org.springframework.samples.petclinic.rest.advice.OwnerCityFullException;
37	import org.springframework.samples.petclinic.rest.advice.OwnerDailyLimitException;
38	import org.springframework.samples.petclinic.mapper.MembershipLevel;
39	import org.springframework.samples.petclinic.mapper.OwnerMapper;
40	import org.springframework.samples.petclinic.mapper.PetMapper;
41	import org.springframework.samples.petclinic.mapper.VisitMapper;
42	import org.springframework.samples.petclinic.model.Owner;
43	import org.springframework.samples.petclinic.model.Pet;
44	import org.springframework.samples.petclinic.model.Visit;
45	import org.springframework.samples.petclinic.rest.api.OwnersApi;
46	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
47	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
48	import org.springframework.samples.petclinic.rest.dto.PetDto;
49	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
50	import org.springframework.samples.petclinic.rest.dto.VisitDto;
51	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
52	import org.springframework.samples.petclinic.service.ClinicService;
53	import org.springframework.security.access.prepost.PreAuthorize;
54	import org.springframework.util.StringUtils;
55	import org.springframework.web.bind.annotation.CrossOrigin;
56	import org.springframework.web.bind.annotation.RequestMapping;
57	import org.springframework.web.bind.annotation.RestController;
58	import org.springframework.web.util.UriComponentsBuilder;
59	
60	import jakarta.transaction.Transactional;
61	
62	/**
63	 * @author Vitaliy Fedoriv
64	 */
65	
66	@RestController
67	@CrossOrigin(exposedHeaders = "errors, content-type")
68	@RequestMapping("/api")
69	public class OwnerRestControllerV1 implements OwnersApi {
70	
71	    /**
72	     * Basic syntactic check for an email address: a non-empty local part, an '@', and a domain with
73	     * at least one dot and a two-or-more letter top-level label. Case is ignored here; accepted
74	     * addresses are lower-cased before being stored.
75	     */
76	    private static final Pattern EMAIL_PATTERN =
77	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
78	
79	    /**
80	     * Dedicated logger for audit side-effects. Emitting audit records on a well-known, separately
81	     * named logger keeps them addressable independently of the class's diagnostic logging.
82	     */
83	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
84	
85	    /**
86	     * Maximum number of owners a single city may contain. A create that would take the owner's city
87	     * to more than this many owners - i.e. the city already holds this many - is rejected with a 409.
88	     */
89	    private static final int CITY_OWNER_LIMIT = 50;
90	
91	    /**
92	     * Maximum number of owners that may be registered on a single day. A create that would take the
93	     * number of owners sharing a {@code registrationDate} beyond this many - i.e. that many owners
94	     * have already been created that day - is rejected with a 429.
95	     */
96	    private static final int DAILY_OWNER_LIMIT = 100;
97	
98	    /**
99	     * Number of owners that must already have been created for a given day before the create
100	     * response flags a bulk sign-up. When more than this many owners already share a
101	     * {@code registrationDate}, the response's {@code bulkSignupWarning} is {@code true}.
102	     */
103	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
104	
105	    private final ClinicService clinicService;
106	
107	    private final OwnerMapper ownerMapper;
108	
109	    private final PetMapper petMapper;
110	
111	    private final VisitMapper visitMapper;
112	
113	    public OwnerRestControllerV1(ClinicService clinicService,
114	                                 OwnerMapper ownerMapper,
115	                                 PetMapper petMapper,
116	                                 VisitMapper visitMapper) {
117	        this.clinicService = clinicService;
118	        this.ownerMapper = ownerMapper;
119	        this.petMapper = petMapper;
120	        this.visitMapper = visitMapper;
121	    }
122	
123	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
124	    @Override
125	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
126	        Collection<Owner> owners;
127	        if (lastName != null) {
128	            owners = this.clinicService.findOwnerByLastName(lastName);
129	        } else {
130	            owners = this.clinicService.findAllOwners();
131	        }
132	        if (owners.isEmpty()) {
133	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
134	        }
135	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
136	    }
137	
138	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
139	    @Override
140	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
141	        Owner owner = this.clinicService.findOwnerById(ownerId);
142	        if (owner == null) {
143	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
144	        }
145	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
146	        ownerDto.setBulkSignupWarning(isBulkSignupDay(owner.getRegistrationDate()));
147	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
148	    }
149	
150	    /**
151	     * Determines whether the supplied day currently holds more than {@link #BULK_SIGNUP_WARNING_THRESHOLD}
152	     * owners sharing that {@code registrationDate}, which flags an unusually high volume of same-day
153	     * owner sign-ups.
154	     *
155	     * @param registrationDate the day to inspect, or {@code null}
156	     * @return {@code true} when more than the threshold of owners are registered on that day
157	     */
158	    private boolean isBulkSignupDay(LocalDate registrationDate) {
159	        return registrationDate != null
160	            && countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
161	    }
162	
163	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
164	    @Override
165	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
166	        ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
167	        validateRequiredFields(ownerFieldsDto);
168	        HttpHeaders headers = new HttpHeaders();
169	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
170	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
171	        owner.setEmail(normalizeEmail(owner.getEmail()));
172	        if (owner.getRegistrationDate() == null) {
173	            owner.setRegistrationDate(LocalDate.now());
174	        }
175	        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
176	        rejectDuplicateOwner(owner, ownerFieldsDto);
177	        if (countOwnersInCity(owner.getCity()) >= CITY_OWNER_LIMIT) {
178	            throw new OwnerCityFullException(owner.getCity());
179	        }
180	        long ownersRegisteredOnDay = countOwnersRegisteredOn(owner.getRegistrationDate());
181	        if (ownersRegisteredOnDay >= DAILY_OWNER_LIMIT) {
182	            throw new OwnerDailyLimitException(owner.getRegistrationDate());
183	        }
184	        boolean bulkSignupWarning = ownersRegisteredOnDay > BULK_SIGNUP_WARNING_THRESHOLD;
185	        owner.setCustomerCode(buildCustomerCode(owner.getCity(), owner.getLastName()));
186	        owner.setHouseholdId(HouseholdNormalizer.householdId(owner.getLastName(), owner.getAddress()));
187	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
188	        owner.setHouseholdSize(countHouseholdMembers(owner.getHouseholdId()) + 1);
189	        this.clinicService.saveOwner(owner);
190	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
191	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
192	            MembershipLevel.forOwner(owner));
193	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
194	        ownerDto.setBulkSignupWarning(bulkSignupWarning);
195	        headers.setLocation(UriComponentsBuilder.newInstance()
196	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
197	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
198	    }
199	
200	    /**
201	     * Rejects an owner payload that is missing or blank in any required field. Collects the name of
202	     * every offending field and, if there is at least one, raises a {@link MissingOwnerFieldsException}
203	     * so the client receives a 400 whose {@code errors} array lists each missing field. The address is
204	     * checked in its {@link AddressNormalizer#normalize normalized} form, so a value that is blank only
205	     * after normalization is still rejected.
206	     *
207	     * @param ownerFieldsDto the submitted owner fields
208	     */
209	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
210	        List<String> missingFields = new ArrayList<>();
211	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
212	            missingFields.add("firstName");
213	        }
214	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
215	            missingFields.add("lastName");
216	        }
217	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
218	            missingFields.add("address");
219	        }
220	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
221	            missingFields.add("city");
222	        }
223	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
224	            missingFields.add("telephone");
225	        }
226	        if (!missingFields.isEmpty()) {
227	            throw new MissingOwnerFieldsException(missingFields);
228	        }
229	    }
230	
231	    /**
232	     * Rejects a submitted owner that would duplicate an existing one. An owner may not reuse another
233	     * owner's telephone or email, and - unless the request opts in with {@code sharesHousehold} - may
234	     * not join a last name and address that already form a household; each collision is reported to the
235	     * client as a 409 Conflict through its own exception. The owner's telephone and email have already
236	     * been normalized, so the comparisons run against their canonical forms.
237	     *
238	     * @param owner the normalized owner about to be created
239	     * @param ownerFieldsDto the submitted owner fields, consulted for the {@code sharesHousehold} opt-in
240	     */
241	    private void rejectDuplicateOwner(Owner owner, OwnerFieldsDto ownerFieldsDto) {
242	        if (isDuplicateTelephone(owner.getTelephone())) {
243	            throw new DuplicateOwnerTelephoneException(owner.getTelephone());
244	        }
245	        if (isDuplicateEmail(owner.getEmail())) {
246	            throw new DuplicateOwnerEmailException(owner.getEmail());
247	        }
248	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())
249	            && isDuplicateHousehold(owner.getLastName(), owner.getAddress())) {
250	            throw new DuplicateOwnerHouseholdException(owner.getLastName(), owner.getAddress());
251	        }
252	    }
253	
254	    /**
255	     * Normalizes an optional email address for owner creation. Email is optional, so a missing or
256	     * blank value is left untouched. When a value is supplied it must be a syntactically valid
257	     * address; the accepted value is lower-cased before it is stored and returned.
258	     *
259	     * @param email the raw email value submitted by the client, or {@code null}
260	     * @return the lower-cased email, or the original blank/{@code null} value when none was supplied
261	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address
262	     */
263	    private String normalizeEmail(String email) {
264	        if (!StringUtils.hasText(email)) {
265	            return email;
266	        }
267	        if (!EMAIL_PATTERN.matcher(email).matches()) {
268	            throw new InvalidOwnerFieldsException(List.of("email"));
269	        }
270	        return email.toLowerCase();
271	    }
272	
273	    /**
274	     * Builds the owner's customer code formatted {@code <CITY3>-<LAST3>-<NNNN>}, where CITY3 is the
275	     * upper-cased first three letters of the city, LAST3 is the upper-cased first three letters of the
276	     * last name and NNNN is a per-city 4-digit zero-padded sequence equal to one more than the number
277	     * of owners already in that city (e.g. {@code SYD-SMI-0007}).
278	     *
279	     * @param city the owner's city
280	     * @param lastName the owner's last name
281	     * @return the assigned customer code
282	     */
283	    private String buildCustomerCode(String city, String lastName) {
284	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
285	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
286	        int sequence = (int) this.clinicService.findAllOwners().stream()
287	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
288	            .count() + 1;
289	        return String.format("%s-%s-%04d", city3, last3, sequence);
290	    }
291	
292	    /**
293	     * Determines whether an existing owner already shares a household with the supplied last name and
294	     * address. Two owners belong to the same household when {@link HouseholdNormalizer#sameHousehold}
295	     * considers their last name and address a match.
296	     *
297	     * @param lastName the submitted owner's last name
298	     * @param address the submitted owner's address
299	     * @return {@code true} if another owner already has the same normalized last name and address
300	     */
301	    /**
302	     * Counts how many owners already exist that share the supplied first and last name, compared
303	     * case-insensitively. This reflects the number of namesakes present <em>before</em> the current
304	     * owner is created and is stored on the new owner as its {@code namesakeCount}.
305	     *
306	     * @param firstName the submitted owner's first name
307	     * @param lastName the submitted owner's last name
308	     * @return the number of existing owners with the same first and last name, ignoring case
309	     */
310	    private int countNamesakes(String firstName, String lastName) {
311	        return (int) this.clinicService.findAllOwners().stream()
312	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
313	                && lastName.equalsIgnoreCase(existing.getLastName()))
314	            .count();
315	    }
316	
317	    /**
318	     * Determines whether an existing owner already uses the supplied telephone, compared by its
319	     * normalized form. The submitted value has already been canonicalized by
320	     * {@link TelephoneNormalizer#normalize}, so this looks up owners holding that exact stored value.
321	     *
322	     * @param telephone the submitted owner's normalized telephone
323	     * @return {@code true} if another owner already uses the same normalized telephone
324	     */
325	    private boolean isDuplicateTelephone(String telephone) {
326	        return !this.clinicService.findOwnerByTelephone(telephone).isEmpty();
327	    }
328	
329	    /**
330	     * Determines whether an existing owner already uses the supplied email, compared by its
331	     * lower-cased form. Email is optional, so a missing or blank value is never considered a
332	     * duplicate. The submitted value has already been lower-cased by {@link #normalizeEmail}, and
333	     * every existing owner's email is compared case-insensitively.
334	     *
335	     * @param email the submitted owner's normalized email, or {@code null}
336	     * @return {@code true} if another owner already uses the same email, ignoring case
337	     */
338	    private boolean isDuplicateEmail(String email) {
339	        if (!StringUtils.hasText(email)) {
340	            return false;
341	        }
342	        return this.clinicService.findAllOwners().stream()
343	            .anyMatch(existing -> email.equalsIgnoreCase(existing.getEmail()));
344	    }
345	
346	    private boolean isDuplicateHousehold(String lastName, String address) {
347	        return this.clinicService.findAllOwners().stream()
348	            .anyMatch(existing -> HouseholdNormalizer.sameHousehold(
349	                lastName, address, existing.getLastName(), existing.getAddress()));
350	    }
351	
352	    /**
353	     * Counts how many existing owners already belong to the supplied household, identified by its
354	     * {@code householdId}. Used when creating an owner to determine the household's size once the new
355	     * owner is added (this count plus one).
356	     *
357	     * @param householdId the normalized household identifier of the owner being created
358	     * @return the number of existing owners already sharing that {@code householdId}
359	     */
360	    private int countHouseholdMembers(String householdId) {
361	        return (int) this.clinicService.findAllOwners().stream()
362	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
363	            .count();
364	    }
365	
366	    /**
367	     * Counts how many owners already live in the supplied city, compared case-insensitively. Used to
368	     * enforce the per-city capacity limit when a new owner is created.
369	     *
370	     * @param city the submitted owner's city
371	     * @return the number of existing owners in that city, ignoring case
372	     */
373	    private long countOwnersInCity(String city) {
374	        return this.clinicService.findAllOwners().stream()
375	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
376	            .count();
377	    }
378	
379	    /**
380	     * Counts how many owners have already been created on the supplied registration date. Used to
381	     * enforce the per-day capacity limit when a new owner is created.
382	     *
383	     * @param registrationDate the registration date of the owner being created
384	     * @return the number of existing owners already registered on that date
385	     */
386	    /**
387	     * Rolls a registration date forward to a business day. A registration date must fall on a
388	     * business day, so when the supplied or defaulted date lands on a Saturday or Sunday it is
389	     * moved forward to the following Monday; a weekday is returned unchanged. Every value derived
390	     * from the registration date (such as the membership number's year segment) and the daily
391	     * create-limit therefore use the adjusted date.
392	     *
393	     * @param date the effective registration date, whether supplied or defaulted to the server date
394	     * @return the same date when it is a weekday, otherwise the next Monday
395	     */
396	    private LocalDate toBusinessDay(LocalDate date) {
397	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
398	            date = date.plusDays(1);
399	        }
400	        return date;
401	    }
402	
403	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
404	        return this.clinicService.findAllOwners().stream()
405	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
406	            .count();
407	    }
408	
409	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
410	    @Override
411	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
412	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
413	        if (currentOwner == null) {
414	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
415	        }
416	        currentOwner.setAddress(ownerFieldsDto.getAddress());
417	        currentOwner.setCity(ownerFieldsDto.getCity());
418	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
419	        currentOwner.setLastName(ownerFieldsDto.getLastName());
420	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
421	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
422	        this.clinicService.saveOwner(currentOwner);
423	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
424	    }
425	
426	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
427	    @Transactional
428	    @Override
429	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
430	        Owner owner = this.clinicService.findOwnerById(ownerId);
431	        if (owner == null) {
432	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
433	        }
434	        this.clinicService.deleteOwner(owner);
435	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
436	    }
437	
438	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
439	    @Override
440	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
441	        Owner owner = this.clinicService.findOwnerById(ownerId);
442	        if (owner == null) {
443	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
444	        }
445	        HttpHeaders headers = new HttpHeaders();
446	        Pet pet = petMapper.toPet(petFieldsDto);
447	        owner.setId(ownerId);
448	        pet.setOwner(owner);
449	        pet.getType().setName(null);
450	        this.clinicService.savePet(pet);
451	        PetDto petDto = petMapper.toPetDto(pet);
452	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
453	            .buildAndExpand(pet.getId()).toUri());
454	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
455	    }
456	
457	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
458	    @Override
459	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
460	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
461	        if (currentOwner != null) {
462	            Pet currentPet = this.clinicService.findPetById(petId);
463	            if (currentPet != null) {
464	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
465	                currentPet.setName(petFieldsDto.getName());
466	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
467	                this.clinicService.savePet(currentPet);
468	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
469	            }
470	        }
471	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
472	    }
473	
474	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
475	    @Override
476	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
477	        HttpHeaders headers = new HttpHeaders();
478	        Visit visit = visitMapper.toVisit(visitFieldsDto);
479	        Pet pet = new Pet();
480	        pet.setId(petId);
481	        visit.setPet(pet);
482	        this.clinicService.saveVisit(visit);
483	        VisitDto visitDto = visitMapper.toVisitDto(visit);
484	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
485	            .buildAndExpand(visit.getId()).toUri());
486	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
487	    }
488	
489	
490	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
491	    @Override
492	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
493	        Owner owner = this.clinicService.findOwnerById(ownerId);
494	        if (owner != null) {
495	            Pet pet = owner.getPet(petId);
496	            if (pet != null) {
497	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
498	            }
499	        }
500	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
501	    }
502	}
