package org.springframework.samples.petclinic.rest.advice;

/**
 * Thrown when a request to create an owner produces an {@code identityKey} - the derived
 * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId} - that exactly matches an
 * existing owner's. This single key consolidates what used to be the separate telephone, email and
 * household duplicate checks, so the {@link ExceptionControllerAdvice} reports it to the client as a
 * 409 Conflict.
 */
public class DuplicateOwnerIdentityException extends RuntimeException {

    private final String identityKey;

    public DuplicateOwnerIdentityException(String identityKey) {
        super("Owner identity already in use: " + identityKey);
        this.identityKey = identityKey;
    }

    public String getIdentityKey() {
        return this.identityKey;
    }

}

